use crate::{scene::Scene,prepared::PreparedMesh,pick_sources::{Mode,Part,Target,Sources},cap_gpu_tests::{renderer,pixels_at,at,wait}};
use session_rust::{Mesh,Point,Color,Session,Xform,proto};use session_rust::mesh::ColorMode;use prost::Message;use std::rc::Rc;
fn panel()->Mesh{let mut m=Mesh::new();for(key,p)in[11,70,803,9004].into_iter().zip([[0.,0.,0.],[1800.,0.,0.],[1800.,1300.,0.],[0.,1300.,0.]]){m.add_vertex(Point::new(p[0],p[1],p[2]),Some(key));}m.add_face(vec![11,70,803,9004],Some(17));m.set_objectcolor(Color::new(0.2,0.4,0.6,1.));m.set_linecolors(vec![],vec![7.]);m}
fn scene(m:Mesh)->Scene{let mut s=Scene::empty();s.insert(PreparedMesh::new(m).unwrap()).unwrap();s}
fn camera()->crate::camera::Camera{let mut c=crate::camera_defaults_tests::top_fixture();c.distance=3000.;c.radius=1500.;c.aspect=4./3.;c}
fn matrix(c:&crate::camera::Camera)->[f32;16]{let mut m=c.uniform();m[12]+=m[15]/320.;m[13]-=m[15]/240.;m}
fn pick(g:&mut super::Renderer,s:&Scene,m:[f32;16],p:[f64;3],mode:Mode)->Option<Target>{g.set_pick_mode(mode);g.request_pick(super::contact_feature_tests::project(m,p),m).unwrap();wait(g);g.take_pick(m).unwrap().unwrap().and_then(|v|g.resolve_pick(s,v))}
fn source(s:&Scene)->(Vec<proto::Session>,serde_json::Value){let b=crate::archive::Bundle::decode(&crate::scene_archive::save(s).unwrap()).unwrap();(b.documents.iter().map(|v|proto::Session::decode(v.as_slice()).unwrap()).collect(),serde_json::to_value(b.metadata).unwrap())}
fn export(name:&str,s:&Scene,image:&[u8]){if let Some(root)=std::env::var_os("VIEWER_MESH_MARKER_PROOF_DIR"){use std::io::Write;let p=std::path::Path::new(&root);std::fs::create_dir_all(p).unwrap();std::fs::write(p.join(format!("{name}.session")),crate::scene_archive::save(s).unwrap()).unwrap();let mut f=std::fs::File::create(p.join(format!("{name}.ppm"))).unwrap();write!(f,"P6\n320 240\n255\n").unwrap();for p in image.chunks_exact(4){f.write_all(&p[..3]).unwrap();}}}

#[test]
fn actual_default_and_authored_mesh_vertices_keep_original_queries(){
 for kind in ["default","authored","ignored"]{let mut mesh=panel();if kind!="default"{mesh.set_pointcolors(vec![Color::new(0.8,0.2,0.4,1.),Color::new(0.1,0.9,0.2,1.),Color::new(0.2,0.3,0.9,1.),Color::new(0.9,0.8,0.1,1.)]);if kind=="ignored"{mesh.color_mode=ColorMode::OBJECTCOLOR;}}
 let s=scene(mesh);let owner=s.objects()[0].id;let original=source(&s);let parts=&s.objects()[0].mesh.parts;assert_eq!(parts.dots.len(),4);assert_eq!(parts.dot_colours.len(),if kind=="authored"{4}else{0});assert_eq!(parts.dots.capacity()*4,16,"Default markers retain endpoint addresses, not duplicate positions");let mut g=renderer(&s);g.set_opacity(1.);g.set_lighting(false,false);assert_eq!(g.point_usage()[0],4);assert_eq!(g.markers.clipping_bytes(),[4,4],"Default mesh and ordinary markers retain one common four-byte metadata record");assert!(g.sources.mesh_markers.is_empty()&&g.sources.mesh_markers.capacity()==0,"Temporary point instances move into the existing upload");let uploads=g.stats()[0];let mut c=camera();
 for projection in [crate::camera::Projection::Orthographic,crate::camera::Projection::Perspective]{c.projection=projection;let m=matrix(&c);for density in [1.,2.]{g.set_density(density);let image=pixels_at(&g,m);assert_eq!(at(&image,160,120),if kind=="authored"{&[204,51,102,255]}else{&[26,26,26,255]},"Actual original vertex11 has its maintained default/authored point color");assert_eq!(pick(&mut g,&s,m,[0.,0.,0.],Mode::Object),Some(Target{owner,part:Part::Object}));assert_eq!(pick(&mut g,&s,m,[900.,650.,0.],Mode::Face),Some(Target{owner,part:Part::Face(17)}));assert_eq!(pick(&mut g,&s,m,[900.,0.,0.],Mode::Edge),Some(Target{owner,part:Part::MeshEdge(11,70)}));assert_eq!(pick(&mut g,&s,m,[0.,0.,0.],Mode::Control),None,"Default dots are not active editing controls");assert!(pixels_at(&g,m)==image);assert_eq!(g.stats()[0],uploads);assert_eq!(source(&s),original);if projection==crate::camera::Projection::Orthographic&&density==1.{export(kind,&s,&image);}}}
 }
}

#[test]
fn source_widths_coplanar_vertices_and_other_families_control_default_dots(){
 let mut m=panel();m.add_vertex(Point::new(-200.,-200.,0.),Some(999999));m.set_linecolors(vec![],vec![0.,0.,7.,0.]);let s=scene(m);assert_eq!(s.objects()[0].mesh.parts.dots.len(),2,"Only the nonzero authored edge contributes endpoints; an isolated source vertex is not a dot");let mut g=renderer(&s);g.set_opacity(1.);assert_eq!(g.point_usage()[0],2);let original=source(&s);let m=matrix(&camera());let image=pixels_at(&g,m);assert_eq!(source(&s),original);export("eligible-edge",&s,&image);
 for widths in [vec![0.],vec![0.;4]]{let mut mesh=panel();mesh.set_linecolors(vec![],widths);let s=scene(mesh);assert!(s.objects()[0].mesh.parts.dots.is_empty());assert!(s.objects()[0].mesh.parts.dot_colours.is_empty());g.set_scene(&s,None);assert_eq!(g.point_usage()[0],0);let before=source(&s);let image=pixels_at(&g,m);assert_eq!(source(&s),before);export("no-dots",&s,&image);}
 let mut fan=Mesh::new();for(key,p)in[11,70,803,9004,500000].into_iter().zip([[-900.,-650.,0.],[900.,-650.,0.],[900.,650.,0.],[-900.,650.,0.],[0.,0.,0.]]){fan.add_vertex(Point::new(p[0],p[1],p[2]),Some(key));}for(face,ring)in [(17,vec![11,70,500000]),(93,vec![70,803,500000]),(125,vec![803,9004,500000]),(302,vec![9004,11,500000])]{fan.add_face(ring,Some(face));}fan.set_objectcolor(Color::new(0.2,0.4,0.6,1.));fan.set_linecolors(vec![],vec![7.]);let s=scene(fan);let original=source(&s);assert_eq!(s.objects()[0].mesh.parts.dots.len(),5,"A source vertex on nonzero coplanar edges remains a maintained dot even when its seam ink is omitted");g.set_scene(&s,None);let image=pixels_at(&g,m);assert_eq!(at(&image,160,120),[26,26,26,255]);assert_eq!(source(&s),original);export("coplanar-center",&s,&image);
 for other in ["surface","brep","plane"]{let mut s=Scene::empty();match other{"surface"=>{s.insert_surface(Rc::new(crate::surface::example())).unwrap();},"brep"=>{s.insert_cad(Rc::new(session_rust::BRep::create_box(1800.,1300.,100.))).unwrap();},_=>{crate::plane_original::insert(&mut s,Rc::new(session_rust::Plane::xy_plane())).unwrap();}}g.set_scene(&s,None);pixels_at(&g,m);assert_eq!(g.point_usage()[0],0,"Other source families keep their own authored glyph policy");}
}

#[test]
fn prepared_marker_addresses_survive_source_unload_and_shared_placement(){
 let mut doc=Session::new("Original marker source");doc.add_mesh(panel(),None);let bytes=doc.to_proto().encode_to_vec();let mut e=crate::editor::Editor::default();e.apply(crate::editor::Action::ReplaceAt(bytes.clone(),Rc::new(crate::reload_url::ReloadUrl::new("test:mesh-markers".into())))).unwrap();let owner=e.scene.objects()[0].id;let display=Rc::clone(&e.scene.objects()[0].mesh);let weak=Rc::downgrade(e.scene.objects()[0].geometry().unwrap());let original=source(&e.scene);let mut g=renderer(&e.scene);g.set_opacity(1.);let m=matrix(&camera());let before=pixels_at(&g,m);let uploads=g.stats()[0];let old=e.scene.placement(owner).unwrap();e.scene.place(owner,&Xform::translation(100.,0.,0.)*&old).unwrap();g.set_scene(&e.scene,None);assert!(pixels_at(&g,m)!=before);e.scene.place(owner,old).unwrap();g.set_scene(&e.scene,None);assert!(pixels_at(&g,m)==before);assert_eq!(g.stats()[0],uploads);assert_eq!(source(&e.scene),original);
 e.apply(crate::editor::Action::UnloadSources).unwrap();assert!(weak.upgrade().is_none());assert!(Rc::ptr_eq(&display,&e.scene.objects()[0].mesh));g.set_scene(&e.scene,None);assert!(pixels_at(&g,m)==before);assert_eq!(g.point_usage()[0],4);assert_eq!(g.stats()[0],uploads);let keys=e.reload_keys();e.hydrate(keys.into_iter().map(|k|(k,bytes.clone())).collect()).unwrap();assert_eq!(source(&e.scene),original);
 for(index,projection)in[crate::camera::Projection::Orthographic,crate::camera::Projection::Perspective].into_iter().enumerate(){let mut c=camera();c.projection=projection;c.grid_plane=Some(crate::cplane::CPlane::Frame{origin:[0.;3],x:[1.,0.,0.],y:[0.,1.,0.]});let now=1000.+index as f64*1000.;g.set_scene(&e.scene,None);g.prepare_origin(&c,&e.scene,None,&[],now).unwrap();let near=g.camera_matrix(&c);let before=pixels_at(&g,near);let uploads=g.stats()[0];let marker_count=g.point_usage()[0];let mut far=e.scene.clone();let anchor=[1_000_000_000.,-1_000_000_000.,1_000_000_000.];far.translate(owner,anchor).unwrap();g.set_scene(&far,None);c.target=anchor;c.grid_plane=Some(crate::cplane::CPlane::Frame{origin:anchor,x:[1.,0.,0.],y:[0.,1.,0.]});assert!(g.prepare_origin(&c,&far,None,&[],now+300.).unwrap().moved);assert_eq!(g.camera_matrix(&c),near);let image=pixels_at(&g,near);assert!(image==before,"Actual production origin preparation preserves all mesh, ink and marker pixels at a billion units");assert_eq!(g.point_usage()[0],marker_count);assert_eq!(marker_count,4);assert_eq!(g.stats()[0],uploads);assert_eq!(g.sources.marker_ids,vec![[owner.value(),0];4]);g.set_pick_mode(Mode::Object);g.request_pick(super::contact_feature_tests::project(near,[0.,0.,0.]),near).unwrap();wait(&g);assert_eq!(g.take_pick(near).unwrap().unwrap().unwrap()[0],owner.value());if index==0{export("rebased-default",&far,&image);}}
 let mesh=panel();let guid=mesh.guid().to_owned();let mut message=crate::instance_specimen::message();message.definitions.as_mut().unwrap().meshes=vec![mesh.to_proto()];for row in &mut message.objects.as_mut().unwrap().instances{row.definition_guid=guid.clone();row.xform=None;row.flags=0;}message.xforms=vec![proto::XformEntry{guid:"first".into(),xform:Some(Xform::translation(-1800.,-650.,0.).to_proto())},proto::XformEntry{guid:"second".into(),xform:Some((&Xform::translation(1800.,-650.,0.)*&Xform::scale_xyz(-0.8,1.2,1.4)).to_proto())}];let mut s=Scene::empty();crate::scene_document::import(&mut s,&message.encode_to_vec(),"",&Xform::identity(),0.).unwrap();assert!(Rc::ptr_eq(&s.objects()[0].mesh,&s.objects()[1].mesh));let original=source(&s);g.set_scene(&s,None);assert_eq!(g.point_usage()[0],8);let mut c=camera();c.distance=6000.;c.radius=3000.;assert!(g.prepare_origin(&c,&s,None,&[],3000.).unwrap().moved);let m=matrix(&c);let image=pixels_at(&g,m);assert!(image.chunks_exact(4).filter(|p|p[2]>p[0].saturating_add(50)).count()>100,"Both actual placed panels must render after restoring the origin");for(i,p)in[[-900.,0.,0.],[1080.,130.,0.]].into_iter().enumerate(){assert_eq!(pick(&mut g,&s,m,p,Mode::Face),Some(Target{owner:s.objects()[i].id,part:Part::Face(17)}));}assert!(pixels_at(&g,m)==image);export("shared-markers",&s,&image);assert_eq!(source(&s),original);
 let id=s.objects()[0].id;let old=s.placement(id).unwrap();s.place(id,Xform::translation(1_000_000_000.125,0.,0.)).unwrap();let prepared=Sources::anchored(&s,[1_000_000_000.,0.,0.]).unwrap();assert_eq!(prepared.mesh_markers[0].center[0],0.125,"Transform after anchoring preserves the source endpoint fraction");s.place(id,old).unwrap();
}
